window.staffList=role=>USERS.filter(u=>u.role&&u.role!=='customer'&&u.active!==false&&(!role||(role==='shopper'?SHOPPER_ROLES:role==='driver'?DRIVER_ROLES:[role]).includes(u.role)||['admin','store_manager'].includes(u.role)));
