/* ---------- live orders + save status ---------- */
let liveNew=0;
CF.live((o,isNew)=>{
  if(isStaffU()){const live=ORDERS.find(x=>x.id===o.id);if(live&&recheckOrder(live))saveAll()}
  if(isNew&&isStaffU()){liveNew++;toast(`New order #${o.id} — ${o.name}`);syslog('New online order #'+o.id)}
  const inBO=(location.hash||'').startsWith('#/admin'),typing=document.activeElement&&/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName),modalOpen=$('modal').classList.contains('on');
  if(inBO&&!typing&&!modalOpen)route();
  else if(!inBO&&((location.hash||'').startsWith('#/order')||(location.hash||'').startsWith('#/orders')))route();
});
const _vBOcf=window.vBO;
window.vBO=function(parts,q){let h=_vBOcf(parts,q);return h.replace('<button class="btn sm ghost" onclick="logout()">Sign out</button>','<span class="livebadge" title="Orders update live"><i></i>Live</span><span id="cfsave" data-s="saved">All changes saved</span><button class="btn sm ghost" onclick="logout()">Sign out</button>')};

/* ---------- time periods for the Order Manager ---------- */
function weekStart(off){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-d.getDay()+off*7);return d}
function perRange(f){const t=new Date();t.setHours(0,0,0,0);const D=n=>ymd(new Date(t.getTime()+n*864e5));
  switch(f.per){case'today':return [D(0),D(0)];case'tomorrow':return [D(1),D(1)];case'yesterday':return [D(-1),D(-1)];
    case'week':return [ymd(weekStart(0)),ymd(new Date(weekStart(0).getTime()+6*864e5))];case'nextweek':return [ymd(weekStart(1)),ymd(new Date(weekStart(1).getTime()+6*864e5))];
    case'lastweek':return [ymd(weekStart(-1)),ymd(new Date(weekStart(-1).getTime()+6*864e5))];case'range':return [f.from||'0000',f.to||'9999'];default:return null}}
const _fqCF=window.fq;window.fq=function(q){const f=_fqCF(q);f.per=q.get('per')||'';f.from=q.get('from')||'';f.to=q.get('to')||'';if(f.per)f.date='';return f};
const _filtCF=window.filt;window.filt=function(f,skip=[]){let r=_filtCF(f,skip);const rg=f.per&&!skip.includes('date')?perRange(f):null;if(rg)r=r.filter(o=>o.date>=rg[0]&&o.date<=rg[1]);return r};
const _fbarCF=window.fbar;window.fbar=function(f,keys){let h=_fbarCF(f,keys);if(!keys.includes('date'))return h;
  const P2=[['','Single day'],['today','Today'],['tomorrow','Tomorrow'],['yesterday','Yesterday'],['week','Current week'],['nextweek','Next week'],['lastweek','Last week'],['range','Specify dates']];
  const sel=`<div><label>Time period</label><select onchange="const p=location.hash.slice(1).split('?')[0];location.hash=p+'?per='+this.value+(this.value?'':'&date=${todayStr()}')">${P2.map(([v,l])=>`<option value="${v}" ${f.per===v?'selected':''}>${l}</option>`).join('')}</select></div>${f.per==='range'?`<div><label>From</label><input type="date" value="${f.from}" onchange="hashSet('from',this.value)"></div><div><label>To</label><input type="date" value="${f.to}" onchange="hashSet('to',this.value)"></div>`:''}`;
  if(f.per)h=h.replace(/<div><label>Day<\/label>[\s\S]*?<\/div><div><label>&nbsp;<\/label><div class="row" style="gap:4px">[\s\S]*?<\/div><\/div>/,'');
  return h.replace('<div class="fbar">','<div class="fbar">'+sel)};

/* ---------- Order Manager: totals bar, map, payment status ---------- */
const payStatus=o=>o.status==='Charged'?'Paid':o.status==='Canceled'?'—':o.status==='Processed'?'Ready to charge':'Authorized';
BO_VIEWS.orders=(f=>q=>{let h=f(q);const fl=filt(fq(q)),ord=fl.reduce((a,o)=>a+(o.total||0),0),proc=fl.filter(o=>o.final).reduce((a,o)=>a+o.final,0),dl=fl.filter(o=>o.method==='Delivery'&&o.status!=='Canceled');
  window._mapIds=dl.map(o=>o.id);
  const bar=`<div class="stats"><div><b>${fl.length}</b>Orders</div><div><b>${money(ord)}</b>Total ordered</div><div><b>${money(proc)}</b>Total processed</div><div><b>${fl.filter(o=>o.status==='Charged').length}</b>Paid</div><div><b>${dl.length}</b>Deliveries <button class="btn sm ghost" style="margin-top:6px" onclick="showMap(window._mapIds)">Show map</button></div></div>`;
  h=h.replace('<div class="schips">',bar+'<div class="schips">');
  return h;})(BO_VIEWS.orders);
function showMap(ids){const os=ids.map(findO).filter(o=>o&&o.address);if(!os.length){toast('No delivery addresses in this view');return}
  const enc=o=>encodeURIComponent(o.address+', '+o.town),origin=encodeURIComponent(S.address||os[0].address+', '+os[0].town);
  const chunks=[];for(let i=0;i<os.length;i+=9)chunks.push(os.slice(i,i+9));
  modal(`<h2>Delivery map</h2><p class="muted small">${os.length} addresses${S.address?' from the store':''}. Google Maps allows 9 stops per route, so long lists are split.</p>
   ${chunks.map((c,i)=>`<p><a class="btn sm lime" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&origin=${origin}&destination=${enc(c[c.length-1])}&waypoints=${c.slice(0,-1).map(enc).join('%7C')}&travelmode=driving">Open route ${chunks.length>1?i+1:''} in Google Maps</a></p>`).join('')}
   <div class="tbl-wrap"><table><tbody>${os.map(o=>`<tr><td>#${o.id}</td><td>${esc(o.name)}</td><td>${esc(o.address)}, ${esc(o.town)}</td><td class="mini">${esc(o.slot)}</td><td><a target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${enc(o)}">View on map</a></td></tr>`).join('')}</tbody></table></div>`);$('mbox').classList.add('wide')}

/* ---------- Order detail: platform, picker & cashier, payment history, resend, cancel ---------- */
BO_VIEWS.order=(f=>(q,rest)=>{let h=f(q,rest);const o=findO(rest[0]);if(!o)return h;
  const saved=o.items.reduce((s,it)=>{const p=prod(it.pid);return s+(p?.sale&&it.mode!=='case'?(p.price-p.sale)*it.qty:0)},0);
  const pays=(o.log||[]).filter(l=>/charge|status: .*charged|voided|payment/i.test(l.m));
  const info=`<div class="panel"><h3>Order info</h3><div class="kv"><b>Platform</b><span>${esc(o.platform||'Web')}</span><b>Placed</b><span>${fmtT(o.created)}</span><b>Payment status</b><span>${payStatus(o)}</span>
   <b>Picker</b><span>${o.shopper?esc(uname(o.shopper)):'—'}${o.pickStart?` · started ${fmtT(o.pickStart)}`:''}${o.pickEnd?` · finished ${fmtT(o.pickEnd)}`:''}</span>
   <b>Cashier</b><span>${o.charge?esc(uname(o.charge.by))+' · charged '+fmtT(o.charge.t)+' · '+money(o.charge.amount):'—'}</span>${saved>0?`<b>You save</b><span>${money(saved)}</span>`:''}${o.ebtAmt?`<b>EBT eligible</b><span>${money(o.ebtAmt)}</span>`:''}${o.tip?`<b>Tip</b><span>${money(o.tip)}</span>`:''}${(o.checks||[]).length?`<b>Checkboxes</b><span class="mini">${o.checks.map(esc).join('<br>')}</span>`:''}</div>
   ${o.address?`<p style="margin:10px 0 0"><a target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(o.address+', '+o.town)}">View address on map</a></p>`:''}
   <h3 style="margin-top:14px">Payment history</h3>${pays.length?`<div class="mini">${pays.map(l=>`${fmtT(l.t)} — ${esc(l.m)}`).join('<br>')}</div>`:'<p class="mini muted">Card authorized for the estimated total at checkout.</p>'}
   <div class="row" style="margin-top:12px;gap:6px"><button class="btn sm ghost" onclick="resendConf('${o.id}')">Resend confirmation</button><button class="btn sm ghost" onclick="chgPay('${o.id}')">Change payment</button>${o.status!=='Canceled'&&o.status!=='Charged'?`<button class="btn sm danger" onclick="boCancel('${o.id}')">Cancel order</button>`:''}</div></div>`;
  return h.replace(/<div>\s*<div class="panel"><h3>Status<\/h3>/,`<div>${info}<div class="panel"><h3>Status</h3>`)})(BO_VIEWS.order);
function resendConf(id){const o=findO(id),name=S.brand?.name||'Center Fresh Supermarket';
  const body=`Hi ${o.name.split(' ')[0]},\n\nThank you for your order #${o.id} with ${name}.\n\n${o.method}: ${prettyDate(o.date)}, ${o.slot}${o.address?'\nAddress: '+o.address+', '+o.town:''}\nItems: ${o.items.length}\nEstimated total: ${money(o.total)}\n\nYou can view or change your order online while it shows "Received".\n\n${name}${S.phone?'\n'+S.phone:''}`;
  location.href=`mailto:${encodeURIComponent(o.email)}?subject=${encodeURIComponent(`${name} — order #${o.id} confirmation`)}&body=${encodeURIComponent(body)}`;o.log.push({t:Date.now(),m:'Confirmation resent',by:me});act('Resent confirmation for #'+id,id);saveAll()}
function chgPay(id){const o=findO(id),opts=['Card — the store will call to authorize','Card on file','Card present','Cash','Check','Pay at pickup / delivery','House account','EBT / SNAP + card'];
  modal(`<h2>Change payment</h2><label for="cpv">Payment for #${o.id}</label><select id="cpv">${opts.map(v=>`<option ${o.pay===v?'selected':''}>${v}</option>`).join('')}</select><button class="btn lime" style="margin-top:12px" onclick="const o=findO('${id}');o.log.push({t:Date.now(),m:'Payment changed: '+o.pay+' → '+cpv.value,by:me});o.pay=cpv.value;act('Payment changed on #${id}','${id}');saveAll();closeModal();route()">Save</button>`)}
function boCancel(id){if(!confirm('Cancel this order? The customer won’t be charged.'))return;const o=findO(id);setOStatus(o,'Canceled','canceled by store');saveAll();route();toast('Order canceled')}

/* ---------- Personal Shopper queue: priority, lines, started, elapsed, flags ---------- */
const elapsed=t=>{if(!t)return '—';const m=Math.round((Date.now()-t)/6e4);return m<60?m+' min':Math.floor(m/60)+'h '+(m%60)+'m'};
BO_VIEWS.shopper=(f=>q=>{const fv=fq(q);if(fv.view!=='full')return f(q);const h=f(q),i=h.indexOf('<nav class="vtabs">'),j=h.indexOf('</nav>',i)+6;
  const PR={High:0,Medium:1,'':2},list=filt(fv).sort((a,b)=>(PR[a.priority||'']-PR[b.priority||''])||a.slot.localeCompare(b.slot)||a.id.localeCompare(b.id));
  const body=list.length?`<div class="panel tbl-wrap"><table><thead><tr><th>Priority</th><th>#</th><th>Customer</th><th>Slot</th><th>Area</th><th>Lines</th><th>Status</th><th>Shopper</th><th>Started</th><th>Elapsed</th><th>Flags</th><th></th></tr></thead><tbody>
   ${list.map(o=>{const [d,n]=pickProgress(o),flags=[o.notes||o.items.some(x=>x.note)?'📝':'',hasProd(o)?'🍲':'',o.status==='On Hold'?'⏸':'',o.items.some(x=>/NO SUBSTITUTE/.test(x.note||''))?'🚫':''].join(' '),late=o.status==='Processing'&&o.pickStart&&Date.now()-o.pickStart>45*6e4;
     return `<tr class="${late?'late':o.status==='Processing'?'started':''}"><td><select style="width:auto;font-size:.8rem" onchange="const o=findO('${o.id}');o.priority=this.value;saveAll();route()" aria-label="Priority">${['','Medium','High'].map(p=>`<option value="${p}" ${(o.priority||'')===p?'selected':''}>${p||'None'}</option>`).join('')}</select></td>
     <td><b>${o.id}</b></td><td>${esc(o.name)}</td><td class="mini">${esc(o.slot)}</td><td class="mini">${o.method==='Delivery'?esc(o.town):'Pickup'}</td><td>${d}/${n}</td><td>${stBadge(o.status)}</td><td class="mini">${o.shopper?esc(uname(o.shopper)):'—'}</td><td class="mini">${o.pickStart?new Date(o.pickStart).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}):'—'}</td><td class="mini">${o.status==='Processing'?elapsed(o.pickStart):'—'}</td><td title="📝 notes · 🍲 production · ⏸ on hold · 🚫 no substitutes">${flags}</td>
     <td>${['Received','Processing','On Hold'].includes(o.status)?`<a class="btn sm" href="#/admin/pick/${o.id}">${o.status==='Received'?'Start':'Continue'}</a>`:`<a class="btn sm ghost" href="#/admin/pick/${o.id}">View</a>`}</td></tr>`}).join('')}</tbody></table><p class="mini muted">Red rows have been picking for over 45 minutes.</p></div>`:'<div class="empty"><div class="e">🧺</div><h3>No orders to pick</h3></div>';
  return h.slice(0,j)+body})(BO_VIEWS.shopper);
const _pkClaimCF=window.pkClaim;window.pkClaim=function(o){_pkClaimCF(o);if(!o.pickStart&&o.status==='Processing')o.pickStart=Date.now()};

/* ---------- Delivery Manager: tabs + trips ---------- */
let TRIPS=DB.get('trips',[]);const saveTrips=()=>DB.set('trips',TRIPS);
BO_VIEWS.delivery=q=>{const f=fq(q),tab=q.get('tab')||'ready',all=filt({...f,method:'Delivery'}).filter(o=>o.status!=='Canceled'&&(realRole()!=='driver'||!o.driver||o.driver===me));
  const packed=o=>['Processed','Charged'].includes(o.status);
  const T={ready:['Ready for Delivery',all.filter(o=>packed(o)&&!['Loading','Out for delivery','Delivered'].includes(o.stage))],loading:['Loading',all.filter(o=>o.stage==='Loading')],out:['Out for Delivery',all.filter(o=>o.stage==='Out for delivery')],history:['History',all.filter(o=>o.stage==='Delivered')]};
  const list=T[tab][1].sort((a,b)=>a.slot.localeCompare(b.slot)||(a.town||'').localeCompare(b.town||'')),drivers=staffList('driver');
  const trips=TRIPS.filter(t=>t.status!=='Done'||tab==='history');
  const row=o=>`<tr><td>${tab==='ready'?`<input type="checkbox" class="dsel" value="${o.id}" aria-label="Select #${o.id}">`:''}</td><td><a href="#/admin/order/${o.id}"><b>${o.id}</b></a></td><td>${esc(o.name)}<div class="mini"><a href="tel:${esc(o.phone)}">${esc(o.phone)}</a></div></td><td>${esc(o.address)}<div class="mini muted">${esc(o.town)}${o.instructions?' · '+esc(o.instructions):''}</div></td><td class="mini">${esc(o.slot)}</td>
    <td><input type="number" min="0" value="${Object.values(o.boxes||{}).reduce((a,n)=>a+(+n||0),0)}" style="width:64px" onchange="const o=findO('${o.id}');o.boxes={Dry:Math.max(0,+this.value||0)};saveAll()" aria-label="Boxes"></td><td class="mini">${o.driver?esc(uname(o.driver)):'—'}</td>
    <td>${tab==='out'?`<button class="btn sm lime" onclick="dlStage('${o.id}','Delivered')">Delivered</button>`:tab==='loading'?`<button class="btn sm" onclick="dlStage('${o.id}','Out for delivery')">Out</button>`:tab==='history'?`<span class="mini">${o.deliveredAt?fmtT(o.deliveredAt):''}</span>`:`<button class="btn sm ghost" onclick="dlStage('${o.id}','Out for delivery')">Out</button>`}</td></tr>`;
  return head('Delivery Manager','Build trips, load the van and track every delivery.',`<button class="btn sm ghost" onclick='routeSheet(${JSON.stringify(list.map(o=>o.id))})'>Print route sheet</button><button class="btn sm ghost" onclick='showMap(${JSON.stringify(list.map(o=>o.id))})'>Show map</button>`)+fbar(f,['date','area','slot','s'])+
  `<nav class="vtabs">${Object.entries(T).map(([k,[l,a]])=>`<a class="${k===tab?'on':''}" href="javascript:hashSet('tab','${k}')">${l} (${a.length})</a>`).join('')}</nav>
  ${tab==='ready'&&list.length?`<div class="bulkbar"><b>New trip:</b><select id="tdrv" style="width:auto"><option value="">Choose driver…</option>${drivers.map(u=>`<option value="${esc(u.email)}">${esc(uname(u.email))}</option>`).join('')}</select><button class="btn sm" onclick="newTrip()">Create trip with selected</button><button class="btn sm ghost" onclick="document.querySelectorAll('.dsel').forEach(c=>c.checked=true)">Select all</button></div>`:''}
  ${tab!=='ready'&&trips.length?trips.filter(t=>tab==='history'?t.status==='Done':tab==='out'?t.status==='Out':t.status==='Loading').map(t=>`<div class="trip"><div class="row" style="justify-content:space-between"><b>Trip ${t.id} · ${esc(uname(t.driver))} · ${t.orders.length} stops</b><div class="row" style="gap:6px"><button class="btn sm ghost" onclick='showMap(${JSON.stringify(t.orders)})'>Route</button><button class="btn sm ghost" onclick='routeSheet(${JSON.stringify(t.orders)})'>Print</button>${t.status==='Loading'?`<button class="btn sm" onclick="tripGo('${t.id}')">Start trip</button>`:t.status==='Out'?`<button class="btn sm lime" onclick="tripDone('${t.id}')">Finish trip</button>`:''}</div></div><div class="mini muted">${t.orders.map(id=>'#'+id).join(' · ')}${t.start?' · left '+fmtT(t.start):''}${t.end?' · back '+fmtT(t.end):''}</div></div>`).join(''):''}
  ${list.length?`<div class="panel tbl-wrap"><table><thead><tr><th></th><th>#</th><th>Customer</th><th>Address</th><th>Slot</th><th>Boxes</th><th>Driver</th><th></th></tr></thead><tbody>${list.map(row).join('')}</tbody></table></div>`:`<div class="empty"><div class="e">🚚</div><h3>Nothing ${T[tab][0].toLowerCase()}</h3><p class="muted">${tab==='ready'?'Orders show here after the shopper completes them.':''}</p></div>`}`};
function newTrip(){const ids=[...document.querySelectorAll('.dsel:checked')].map(c=>c.value),drv=$('tdrv').value;if(!ids.length){toast('Select orders for the trip');return}if(!drv){toast('Choose a driver');return}
  const t={id:String((TRIPS.reduce((a,x)=>Math.max(a,+x.id||0),0))+1),driver:drv,orders:ids,status:'Loading',created:Date.now()};TRIPS.push(t);
  ids.forEach(id=>{const o=findO(id);o.driver=drv;o.stage='Loading';o.trip=t.id;o.log.push({t:Date.now(),m:`Trip ${t.id} · ${uname(drv)}`,by:me})});saveTrips();saveAll();act(`Created trip ${t.id} (${ids.length} stops)`);location.hash='#/admin/delivery?tab=loading'}
function tripGo(id){const t=TRIPS.find(x=>x.id===id);t.status='Out';t.start=Date.now();t.orders.forEach(oid=>{const o=findO(oid);if(o&&o.stage!=='Delivered'){o.stage='Out for delivery';o.outAt=Date.now()}});saveTrips();saveAll();act('Trip '+id+' left the store');location.hash='#/admin/delivery?tab=out'}
function tripDone(id){const t=TRIPS.find(x=>x.id===id),left=t.orders.map(findO).filter(o=>o&&o.stage!=='Delivered');if(left.length&&!confirm(`${left.length} stop(s) aren’t marked delivered. Mark them delivered and finish?`))return;
  left.forEach(o=>{o.stage='Delivered';o.deliveredAt=Date.now()});t.status='Done';t.end=Date.now();saveTrips();saveAll();act('Trip '+id+' finished');route()}

/* ---------- Pickup Manager tabs ---------- */
BO_VIEWS.pickup=q=>{const f=fq(q),tab=q.get('tab')||'ready',all=filt({...f,method:'Pickup'}).filter(o=>o.status!=='Canceled');
  const T={ready:['Ready for Pickup',all.filter(o=>['Processed','Charged'].includes(o.status)&&o.stage!=='Picked up')],picking:['Being picked',all.filter(o=>!['Processed','Charged'].includes(o.status))],history:['History',all.filter(o=>o.stage==='Picked up')]};
  const list=T[tab][1].sort((a,b)=>a.slot.localeCompare(b.slot));
  return head('Pickup Manager','Customer pickups at the store.')+fbar(f,['date','slot','s'])+`<nav class="vtabs">${Object.entries(T).map(([k,[l,a]])=>`<a class="${k===tab?'on':''}" href="javascript:hashSet('tab','${k}')">${l} (${a.length})</a>`).join('')}</nav>
  ${list.length?`<div class="panel tbl-wrap"><table><thead><tr><th>#</th><th>Customer</th><th>Slot</th><th>Boxes</th><th>Order</th><th>Paid</th><th></th></tr></thead><tbody>${list.map(o=>`<tr><td><a href="#/admin/order/${o.id}"><b>${o.id}</b></a></td><td>${esc(o.name)}<div class="mini"><a href="tel:${esc(o.phone)}">${esc(o.phone)}</a></div></td><td class="mini">${esc(o.slot)}</td><td class="mini">${Object.entries(o.boxes||{}).filter(([,n])=>n).map(([k,n])=>n+' '+k).join(', ')||'—'}</td><td>${stBadge(o.status)}</td>
   <td>${o.status==='Charged'?'✅':can('charge')&&o.status==='Processed'?`<a class="btn sm ghost" href="#/admin/charge/${o.id}">Charge</a>`:'—'}</td><td>${tab==='ready'?`<button class="btn sm lime" onclick="puDone('${o.id}')">Picked up</button>`:tab==='history'?`<span class="mini">${o.pickedAt?fmtT(o.pickedAt):''}</span>`:''}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div class="e">🛍️</div><h3>Nothing here</h3></div>`}`};

/* ---------- Production Manager: by item / by order, processed ---------- */
BO_VIEWS.production=q=>{const f=fq(q),by=q.get('by')||'item',st=q.get('st')||'open',os=filt(f).filter(o=>o.status!=='Canceled');
  const lines=[];os.forEach(o=>o.items.forEach((it,i)=>{if(isProdItem(it))lines.push({o,it,i,p:prod(it.pid)})}));
  const L=lines.filter(l=>st==='all'||(st==='open'?!l.it.prodDone:l.it.prodDone));window._prodX=L.map(l=>({Order:l.o.id,Customer:l.o.name,Slot:l.o.slot,Department:l.p?.dept,Item:l.it.name,Qty:qtyLabel(l.it,l.p),Note:l.it.note||'',Processed:l.it.prodDone?'yes':''}));
  const btn=l=>l.it.prodDone?`<button class="btn sm ghost" onclick="prDone('${l.o.id}',${l.i},false);route()">Undo</button>`:`<button class="btn sm lime" onclick="prDone('${l.o.id}',${l.i},true);route()">Processed</button>`;
  let body='';
  if(by==='item'){const g={};L.forEach(l=>{(g[l.it.pid]=g[l.it.pid]||[]).push(l)});
    body=Object.values(g).sort((a,b)=>a[0].p.dept.localeCompare(b[0].p.dept)||a[0].p.name.localeCompare(b[0].p.name)).map(ls=>{const p=ls[0].p,qty=ls.reduce((a,l)=>a+(l.it.mode==='case'?0:l.it.qty),0);
      return `<details class="ocard" ${q.get('x')?'open':''}><summary class="row" style="justify-content:space-between;list-style:none;cursor:pointer"><span class="row" style="gap:10px;flex-wrap:nowrap"><span class="${tcls(p)}" style="width:44px;height:44px;font-size:1.3rem">${pimg(p)}</span><span><b>${esc(p.name)}</b><div class="mini muted">${esc(p.dept)} · ${ls.length} order${ls.length>1?'s':''}</div></span></span><b style="font-size:1.2rem">${+qty.toFixed(2)}${p.unit==='lb'?' lb':''}</b></summary>
       <table style="margin-top:8px"><tbody>${ls.map(l=>`<tr><td><a href="#/admin/order/${l.o.id}">#${l.o.id}</a> ${esc(l.o.name)}</td><td class="mini">${esc(l.o.slot)}</td><td>${qtyLabel(l.it,p)}</td><td class="mini">${l.it.note?'“'+esc(l.it.note)+'”':''}</td><td>${btn(l)}</td></tr>`).join('')}</tbody></table></details>`}).join('')}
  else{const g={};L.forEach(l=>{(g[l.o.id]=g[l.o.id]||[]).push(l)});
    body=Object.values(g).sort((a,b)=>a[0].o.slot.localeCompare(b[0].o.slot)).map(ls=>`<details class="ocard" ${q.get('x')?'open':''}><summary style="cursor:pointer"><b>#${ls[0].o.id} · ${esc(ls[0].o.name)}</b> <span class="mini muted">${esc(ls[0].o.slot)} · ${ls.length} prep item${ls.length>1?'s':''}</span></summary><table style="margin-top:8px"><tbody>${ls.map(l=>`<tr><td>${esc(l.it.name)}</td><td>${qtyLabel(l.it,l.p)}</td><td class="mini">${l.it.note?'“'+esc(l.it.note)+'”':''}</td><td>${btn(l)}</td></tr>`).join('')}</tbody></table></details>`).join('')}
  return head('Production Manager',`Prep for ${esc(prodDepts().join(', '))}.`,`<button class="btn sm ghost" onclick="hashSet('x',${q.get('x')?"''":"'1'"})">${q.get('x')?'Collapse all':'Expand all'}</button><button class="btn sm ghost" onclick="xlsx(window._prodX,'Production','CenterFresh_Production.xlsx')">Export to Excel</button><button class="btn sm ghost" onclick="printProd()">Print</button>`)+fbar(f,['date','slot','area'])+
   `<div class="schips">${[['item','By item'],['order','By order']].map(([k,l])=>`<a class="${by===k?'on':''}" href="javascript:hashSet('by','${k}')">${l}</a>`).join('')}<span style="width:12px"></span>${[['open','To prepare'],['done','Processed'],['all','All']].map(([k,l])=>`<a class="${st===k?'on':''}" href="javascript:hashSet('st','${k}')">${l} <b>${k==='all'?lines.length:lines.filter(x=>k==='open'?!x.it.prodDone:x.it.prodDone).length}</b></a>`).join('')}</div>
   ${body||'<div class="empty"><div class="e">🍲</div><h3>Nothing to prepare</h3><p class="muted">Items from production departments show here (Settings → Production Settings).</p></div>'}`};

/* ---------- Order Items: Not done / Done / Not available, brand filter, monitor ---------- */
let monTimer=null;
BO_VIEWS['order-items']=q=>{const f=fq(q),st=q.get('st')||'notdone',dep=q.get('dept')||'',br=q.get('brand')||'',os=filt(f).filter(o=>o.status!=='Canceled');
  const rows={};os.forEach(o=>o.items.forEach(it=>{const pk=it.pick?.status,s=pk==='out'?'na':pk?'done':'notdone';if(st!=='all'&&s!==st)return;const p=prod(it.pid);if(dep&&p?.dept!==dep)return;if(br&&brandOf(p||{})!==br)return;
    const k=it.pid+'|'+it.mode;rows[k]=rows[k]||{p,name:it.name,mode:it.mode,qty:0,orders:new Set(),notes:0};rows[k].qty+=it.qty;rows[k].orders.add(o.id);if(it.note)rows[k].notes++}));
  const R=Object.values(rows).sort((a,b)=>(S.pickRoute.indexOf(a.p?.dept)+100)%100-(S.pickRoute.indexOf(b.p?.dept)+100)%100||(a.p?.sub||'').localeCompare(b.p?.sub||'')||a.name.localeCompare(b.name));
  window._oi=R.map(r=>({Department:r.p?.dept,Category:r.p?.sub,Brand:brandOf(r.p||{}),Product:r.name,UPC:r.p?.upc||'',Quantity:+r.qty.toFixed(2),Unit:r.mode==='case'?'case':r.p?.unit,Orders:r.orders.size,Notes:r.notes}));
  const brands=[...new Set(os.flatMap(o=>o.items.map(it=>brandOf(prod(it.pid)||{}))).filter(Boolean))].sort();
  clearInterval(monTimer);if(q.get('mon'))monTimer=setInterval(()=>{if((location.hash||'').includes('order-items')&&!document.activeElement?.matches('input,select'))route();else clearInterval(monTimer)},30000);
  return head('Order Items','Every item ordered, in pick-route order.',`<button class="btn sm ${q.get('mon')?'lime':'ghost'}" onclick="hashSet('mon',${q.get('mon')?"''":"'1'"})">${q.get('mon')?'Monitoring (30s)':'Monitor'}</button><button class="btn sm ghost" onclick="xlsx(window._oi,'Order Items','CenterFresh_Order_Items.xlsx')">Export</button><button class="btn sm ghost" onclick="printProd()">Print</button>`)+
   fbar(f,['date','slot','area']).replace('<div class="fbar">',`<div class="fbar"><div><label>Department</label><select onchange="hashSet('dept',this.value)"><option value="">All</option>${DEPT_NAMES.map(d=>`<option ${d===dep?'selected':''}>${esc(d)}</option>`).join('')}</select></div><div><label>Brand</label><select onchange="hashSet('brand',this.value)"><option value="">All</option>${brands.map(b=>`<option ${b===br?'selected':''}>${esc(b)}</option>`).join('')}</select></div>`)+
   `<div class="schips">${[['notdone','Not Done'],['done','Done'],['na','Not Available'],['all','All']].map(([k,l])=>`<a class="${st===k?'on':''}" href="javascript:hashSet('st','${k}')">${l}</a>`).join('')}</div>
   <p class="mini muted">${os.length} orders · ${R.length} products</p>${R.length?`<div class="panel tbl-wrap"><table><thead><tr><th></th><th>Product</th><th>Aisle</th><th>Qty</th><th>Orders</th><th>Notes</th></tr></thead><tbody>${R.map(r=>`<tr><td>${r.p?`<span class="${tcls(r.p)}" style="width:40px;height:40px;font-size:1.2rem">${pimg(r.p)}</span>`:''}</td><td><b>${esc(r.name)}</b><div class="mini muted">${esc(brandOf(r.p||{}))} ${esc(r.p?.size||'')}</div></td><td class="mini">${esc(r.p?.dept||'')} › ${esc(r.p?.sub||'')}</td><td><b>${+r.qty.toFixed(2)}</b> ${r.mode==='case'?'case':r.p?.unit==='lb'?'lb':''}</td><td>${r.orders.size}</td><td>${r.notes||''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><div class="e">📋</div><h3>Nothing here</h3></div>'}`};

/* ---------- Stock Control: who reported out of stock, when; report in stock ---------- */
EDIT_KEYS.push('oosBy','oosAt','lastSold');
const _stOosCF=window.stOos;window.stOos=function(id,v){const p=prod(id);if(v){p.oosBy=me;p.oosAt=Date.now()}else{p.oosBy=null;p.oosAt=null}_stOosCF(id,v)};
const _pkMarkCF=window.pkMark;window.pkMark=function(id,i,st){const it=findO(id)?.items[i];if(st==='out'&&it){const p=prod(it.pid);if(p&&S.stockCtl.oosOnPick&&!p.oos){p.oosBy=me;p.oosAt=Date.now()}}_pkMarkCF(id,i,st)};
const lastSold=pid=>{let t=0;ORDERS.forEach(o=>{if(o.status==='Charged'&&o.items.some(i=>i.pid===pid))t=Math.max(t,o.charge?.t||o.created)});return t};
BO_VIEWS.stock=(f=>q=>{if((q.get('show')||'')!=='oos')return f(q);const list=P.filter(oosP).sort((a,b)=>(b.oosAt||0)-(a.oosAt||0));
  window._oos=list.map(p=>({Product:p.name,Size:p.size,Department:p.dept,Category:p.sub,UPC:p.upc||'',LastSold:lastSold(p.id)?new Date(lastSold(p.id)).toLocaleDateString():'',ReportedBy:uname(p.oosBy),Reported:p.oosAt?new Date(p.oosAt).toLocaleString():''}));
  const h=f(new URLSearchParams('show=oos')),i=h.indexOf('<p class="mini muted">');
  return h.slice(0,i)+`<div class="bulkbar"><b id="oosn">0 selected</b><button class="btn sm lime" onclick="bulkInStock()">Report in stock</button><button class="btn sm ghost" onclick="xlsx(window._oos,'Out of stock','CenterFresh_Out_of_Stock.xlsx')">Export to Excel</button></div>
  ${list.length?`<div class="panel tbl-wrap"><table><thead><tr><th><input type="checkbox" onchange="document.querySelectorAll('.oosc').forEach(c=>c.checked=this.checked);oosCnt()" aria-label="Select all"></th><th>Product</th><th>Location</th><th>UPC</th><th>Last sold</th><th>Reported by</th><th>Reported</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><input type="checkbox" class="oosc" value="${p.id}" onchange="oosCnt()" aria-label="Select"></td><td><b>${esc(p.name)}</b><div class="mini muted">${esc(p.size)}</div></td><td class="mini">${esc(p.dept)} › ${esc(p.sub)}</td><td class="mini">${esc(p.upc||'')}</td><td class="mini">${lastSold(p.id)?new Date(lastSold(p.id)).toLocaleDateString():'—'}</td><td class="mini">${p.oosBy?esc(uname(p.oosBy)):'—'}</td><td class="mini">${p.oosAt?fmtT(p.oosAt):'—'}</td><td><button class="btn sm ghost" onclick="stOos('${p.id}',false);route()">Report in stock</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><div class="e">✅</div><h3>Nothing is out of stock</h3></div>'}`})(BO_VIEWS.stock);
function oosCnt(){$('oosn').textContent=document.querySelectorAll('.oosc:checked').length+' selected'}
function bulkInStock(){const ids=[...document.querySelectorAll('.oosc:checked')].map(c=>c.value);if(!ids.length){toast('Select items first');return}ids.forEach(id=>{const p=prod(id);p.oos=undefined;p.oosBy=null;p.oosAt=null});act(`Reported ${ids.length} items back in stock`);saveAll();route();toast(`${ids.length} items back in stock`)}

/* ---------- Data Issues reported by staff ---------- */
let ISSUES=DB.get('issues',[]);const saveIssues=()=>DB.set('issues',ISSUES);
function reportIssue(pid){const p=prod(pid);modal(`<h2>Report a data issue</h2><p class="muted">${esc(p?.name||'')}</p><label for="isk">What’s wrong?</label><select id="isk"><option>Wrong price</option><option>Wrong picture</option><option>Wrong name or size</option><option>Wrong category</option><option>Wrong barcode / UPC</option><option>Discontinued</option><option>Other</option></select><label for="isn">Details</label><textarea id="isn" rows="3"></textarea><button class="btn lime" style="margin-top:12px" onclick="ISSUES.unshift({id:Date.now(),pid:'${pid}',name:${qa(p?.name||'')},kind:isk.value,note:isn.value,by:me,t:Date.now(),fixed:false});saveIssues();act('Reported data issue: '+isk.value,'${pid}');closeModal();toast('Thanks — issue reported')">Report issue</button>`)}
const _editPCF=window.editP;window.editP=function(id){_editPCF(id);if(id){const r=document.querySelector('#mbox .row:last-child');r?.insertAdjacentHTML('beforeend',`<button class="btn ghost" type="button" onclick="reportIssue('${id}')">Report data issue</button>`)}};
BO_VIEWS.issues=(f=>q=>{const show=q.get('fx')||'open',L=ISSUES.filter(i=>show==='all'||(show==='open'?!i.fixed:i.fixed));window._iss=ISSUES.map(i=>({Product:i.name,Issue:i.kind,Details:i.note,ReportedBy:uname(i.by),Reported:new Date(i.t).toLocaleString(),Fixed:i.fixed?'yes':'no'}));
  const rep=`<div class="panel tbl-wrap"><div class="row" style="justify-content:space-between"><h3 style="margin:0">Reported by staff</h3><div class="row"><div class="schips" style="margin:0">${[['open','Not fixed'],['fixed','Fixed'],['all','All']].map(([k,l])=>`<a class="${show===k?'on':''}" href="javascript:hashSet('fx','${k}')">${l} <b>${ISSUES.filter(i=>k==='all'||(k==='open'?!i.fixed:i.fixed)).length}</b></a>`).join('')}</div><button class="btn sm ghost" onclick="xlsx(window._iss,'Data issues','CenterFresh_Data_Issues.xlsx')">Export</button></div></div>
   ${L.length?`<table style="margin-top:10px"><thead><tr><th>Product</th><th>Issue</th><th>Reported by</th><th>When</th><th>Fixed</th><th></th></tr></thead><tbody>${L.map(i=>`<tr><td><b>${esc(i.name)}</b></td><td>${esc(i.kind)}<div class="mini muted">${esc(i.note||'')}</div></td><td class="mini">${esc(uname(i.by))}</td><td class="mini">${fmtT(i.t)}</td><td><input type="checkbox" ${i.fixed?'checked':''} onchange="const x=ISSUES.find(z=>z.id===${i.id});x.fixed=this.checked;x.fixedBy=me;saveIssues();route()" aria-label="Fixed"></td><td>${prod(i.pid)?`<button class="btn sm ghost" onclick="editP('${i.pid}')">Fix</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<p class="muted">No reported issues. Staff can report one from any product’s Edit window.</p>'}</div><h2 style="font-size:1.2rem;margin-top:22px">Automatic checks</h2>`;
  return f(q).replace('<div class="schips">',rep+'<div class="schips">')})(BO_VIEWS.issues);

/* ---------- Check Products: look up a picture by SKU / UPC ---------- */
BO_VIEWS.check=(f=>q=>f(q).replace('<div class="fbar">',`<div class="panel row"><label for="skul" style="margin:0">Look up by SKU / UPC / ID</label><input id="skul" style="max-width:260px" placeholder="Scan or type a code" onkeydown="if(event.key==='Enter')skuLook(this.value)"><button class="btn sm" onclick="skuLook(skul.value)">Look up</button></div><div class="fbar">`))(BO_VIEWS.check);
function skuLook(v){v=String(v||'').trim();const p=P.find(x=>x.upc===v||x.id===v||x.id==='c'+v);if(!p){toast('No product with that code');return}
  modal(`<div class="row" style="gap:16px;align-items:flex-start;flex-wrap:nowrap"><span class="${tcls(p)}" style="width:180px;height:180px;font-size:4rem;flex-shrink:0">${pimg(p)}</span><div><h2 style="margin-top:0">${esc(p.name)}</h2><p class="muted">${esc(p.size)} · ${esc(p.dept)} › ${esc(p.sub)}<br>ID ${esc(p.id)}${p.upc?' · UPC '+esc(p.upc):''}</p><p>${priceHTML(p)}</p><div class="row"><button class="btn sm" onclick="editP('${p.id}')">Edit</button><button class="btn sm ghost" onclick="reportIssue('${p.id}')">Report issue</button></div></div></div>`)}

/* ---------- Reports: platform, service area, marketing lists, fill rate ---------- */
BO_VIEWS.reports=(f=>q=>{let h=f(q);const type=q.get('t')||'sales',from=q.get('from')||ymd(new Date(Date.now()-29*864e5)),to=q.get('to')||todayStr();
  const os=ORDERS.filter(o=>o.date>=from&&o.date<=to&&o.status!=='Canceled'),T=o=>o.finalT||totals(o,['Processed','Charged'].includes(o.status));
  const grp=(key)=>{const m={};os.forEach(o=>{const k=key(o)||'—';m[k]=m[k]||{n:0,v:0};m[k].n++;m[k].v+=T(o).total});return Object.entries(m).sort((a,b)=>b[1].v-a[1].v)};
  const tbl=(title,rows)=>`<div class="panel tbl-wrap"><h3>${title}</h3><table><thead><tr><th></th><th>Orders</th><th>Sales</th></tr></thead><tbody>${rows.map(([k,x])=>`<tr><td>${esc(k)}</td><td>${x.n}</td><td>${money(x.v)}</td></tr>`).join('')||'<tr><td class="muted">No orders</td></tr>'}</tbody></table></div>`;
  if(type==='sales'){const top={};os.forEach(o=>o.items.forEach(it=>{top[it.pid]=top[it.pid]||{n:it.name,q:0,v:0};top[it.pid].q+=it.qty;top[it.pid].v+=lineTotal(it)}));
    const wk=grp(o=>{const d=new Date(o.date+'T00:00');d.setDate(d.getDate()-d.getDay());return 'Week of '+ymd(d)+(o.platform==='Phone'?' · phone':' · online')});
    h+=`<div class="dgrid">${tbl('By platform',grp(o=>o.platform||'Web'))}${tbl('By service area',grp(o=>o.method==='Pickup'?'In-store pickup':o.town))}</div>${tbl('Phone vs. online by week',wk)}
     <div class="panel tbl-wrap"><h3>Top products</h3><table><thead><tr><th>Product</th><th>Qty</th><th>Sales</th></tr></thead><tbody>${Object.values(top).sort((a,b)=>b.v-a.v).slice(0,25).map(x=>`<tr><td>${esc(x.n)}</td><td>${+x.q.toFixed(2)}</td><td>${money(x.v)}</td></tr>`).join('')}</tbody></table></div>`}
  if(type==='marketing'){const L=q.get('list')||'never',cust=USERS.filter(u=>(u.role||'customer')==='customer'),byE={};ORDERS.filter(o=>o.status!=='Canceled').forEach(o=>(byE[o.email]=byE[o.email]||[]).push(o));
    const first=e=>(byE[e]||[]).reduce((a,o)=>Math.min(a,o.created),Infinity),last=e=>(byE[e]||[]).reduce((a,o)=>Math.max(a,o.created),0);
    const F={never:['Never ordered',u=>!byE[u.email]],cart:['Has items in cart',u=>(u.cart||[]).length>0],recent:['Registered in this period',u=>u.created&&ymd(new Date(u.created))>=from&&ymd(new Date(u.created))<=to],firstin:['First order in this period',u=>byE[u.email]&&ymd(new Date(first(u.email)))>=from&&ymd(new Date(first(u.email)))<=to],lapsed:['No order since this period started',u=>byE[u.email]&&ymd(new Date(last(u.email)))<from]};
    const list=cust.filter(F[L][1]);window._mk=list.map(u=>({First:u.first||'',Last:u.last||'',Email:u.email,Phone:u.phone||'',Orders:(byE[u.email]||[]).length,LastOrder:last(u.email)?new Date(last(u.email)).toLocaleDateString():'',CartItems:(u.cart||[]).length,Group:u.group||''}));
    h+=`<div class="panel tbl-wrap"><div class="row" style="justify-content:space-between"><h3 style="margin:0">Customer lists</h3><button class="btn sm ghost" onclick="xlsx(window._mk,'Customers','CenterFresh_${L}_customers.xlsx')">Export to Excel</button></div><div class="schips" style="margin-top:10px">${Object.entries(F).map(([k,[l]])=>`<a class="${k===L?'on':''}" href="javascript:hashSet('list','${k}')">${l} <b>${cust.filter(F[k][1]).length}</b></a>`).join('')}</div>
     <table><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Orders</th><th>Cart</th></tr></thead><tbody>${list.slice(0,300).map(u=>`<tr><td>${esc((u.first||'')+' '+(u.last||''))}</td><td class="mini">${esc(u.email)}</td><td class="mini">${esc(u.phone||'')}</td><td>${(byE[u.email]||[]).length}</td><td>${(u.cart||[]).length||''}</td></tr>`).join('')||'<tr><td class="muted">Nobody in this list</td></tr>'}</tbody></table></div>`}
  if(type==='shopper'){const m={};os.filter(o=>['Processed','Charged'].includes(o.status)).forEach(o=>{const k=o.shopper||'';const r=m[k]=m[k]||{lines:0,filled:0,lost:0,orders:0};r.orders++;o.items.forEach(it=>{r.lines++;if(it.pick?.status==='out')r.lost+=lineTotal(it);else r.filled++})});
    h+=`<div class="panel tbl-wrap"><h3>Fill rate & lost sales</h3><table><thead><tr><th>Shopper</th><th>Orders</th><th>Lines</th><th>Fill rate</th><th>Lost sales</th></tr></thead><tbody>${Object.entries(m).map(([k,r])=>`<tr><td>${k?esc(uname(k)):'Unassigned'}</td><td>${r.orders}</td><td>${r.lines}</td><td>${r.lines?Math.round(r.filled/r.lines*100)+'%':'—'}</td><td>${money(r.lost)}</td></tr>`).join('')||'<tr><td class="muted">No picked orders</td></tr>'}</tbody></table></div>`}
  return h})(BO_VIEWS.reports);

/* ---------- Bulk Edit: import a list of SKUs / UPCs ---------- */
BO_VIEWS.bulk=(f=>q=>{const sk=(DB.get('skus','')||'');let h=f(q);
  if(sk){const set=new Set(sk.split(/[\s,]+/).filter(Boolean));window._bulk=(window._bulk||[]).filter(id=>{const p=prod(id);return set.has(id)||set.has(p?.upc)||set.has(String(id).replace(/^c/,''))})}
  return h.replace('<div class="panel"><h3>',`<div class="panel row" style="justify-content:space-between"><span>${sk?`<b>Filtered to ${window._bulk.length} imported SKUs</b>`:'Paste or scan a list of SKUs / UPCs to edit just those products.'}</span><span class="row"><button class="btn sm ghost" onclick="skuImport()">Import SKUs</button>${sk?'<button class="btn sm ghost" onclick="DB.set(\'skus\',\'\');route()">Clear SKU list</button>':''}</span></div><div class="panel"><h3>`)})(BO_VIEWS.bulk);
function skuImport(){modal(`<h2>Import SKUs</h2><p class="muted">One code per line (UPC, SKU or product ID). A barcode scanner types into this box too.</p><textarea id="skt" rows="8"></textarea><button class="btn lime" style="margin-top:12px" onclick="DB.set('skus',skt.value);closeModal();route()">Use these SKUs</button>`)}
try{localStorage}catch(e){}
(()=>{const o=window.CFDB.get;window.CFDB.get=(k,d)=>k==='skus'?(sessionStorage.getItem('cf_skus')||d):o(k,d);const s=window.CFDB.set;window.CFDB.set=(k,v)=>k==='skus'?sessionStorage.setItem('cf_skus',v):s(k,v)})();

/* ---------- Settings: service areas, store general, checkout, shopper mode, slot calendar ---------- */
BO_VIEWS.settings=(f=>q=>{const s=q.get('s')||'general';if(roleOf()!=='admin')return f(q);
  const shell=b=>{const h=f(new URLSearchParams('s=box'));return h.replace(/<h2>Box Types<\/h2>[\s\S]*$/,b).replace('class="on" href="#/admin/settings?s=box"','href="#/admin/settings?s=box"').replace(`class="" href="#/admin/settings?s=${s}"`,`class="on" href="#/admin/settings?s=${s}"`)};
  if(s==='areas')return shell(`<h2>Service Areas</h2><div class="panel tbl-wrap"><p class="muted small">Each area has its own fee, minimum and an optional lower fee for bigger orders. ZIP codes are for your reference and the delivery map.</p><table><thead><tr><th>Area</th><th>Fee</th><th>Minimum</th><th>Lower fee over</th><th>Lower fee</th><th>ZIP codes</th><th>Active</th><th></th></tr></thead><tbody>${S.areas.map((a,i)=>`<tr class="arr2"><td><input value="${esc(a.name)}" style="min-width:130px"></td><td><input type="number" step="0.01" value="${a.fee}" style="width:80px"></td><td><input type="number" step="0.01" value="${a.min}" style="width:80px"></td><td><input type="number" step="0.01" value="${a.discOver||''}" placeholder="—" style="width:80px"></td><td><input type="number" step="0.01" value="${a.discFee??''}" placeholder="—" style="width:80px"></td><td><input value="${esc(a.zips||'')}" placeholder="11219, 11204"></td><td><input type="checkbox" ${a.active?'checked':''}></td><td><button class="linkbtn red" onclick="S.areas.splice(${i},1);saveSet('Service areas');route()">Remove</button></td></tr>`).join('')}</tbody></table>
    <label for="nsd">Store no-service days (YYYY-MM-DD, comma separated — holidays, closures)</label><input id="nsd" value="${esc(S.noServiceDays||'')}" placeholder="2026-12-25, 2027-01-01">
    <label for="puf">Pickup fee ($)</label><input id="puf" type="number" step="0.01" value="${S.pickupFee??''}" placeholder="Same as service fee" style="max-width:160px">
    <div class="row" style="margin-top:12px"><button class="btn sm ghost" onclick="S.areas.push({name:'New area',fee:S.fee,min:S.minOrder,zips:'',active:false,discOver:0,discFee:null});route()">Add area</button><button class="btn" onclick="arSave2()">Save</button></div></div>`);
  if(s==='general')return f(q).replace('<form onsubmit="return saveSettings(event)">',`<div class="panel"><h3>Site message & options</h3><label for="sm1">Message at the top of every page</label><input id="sm1" value="${esc(S.siteMsg||'')}">
    <label for="sm2">Door / delivery policy (shown on Delivery Info)</label><input id="sm2" value="${esc(S.doorPolicy||'')}"><label for="sm3">Tip choices at checkout (%)</label><input id="sm3" value="${esc((S.tipOptions||[0,5,10,15]).join(', '))}">
    ${chk('sm4',S.noAlcohol,'We don’t sell alcohol online')}${chk('sm5',S.googleLogin,'Show “Continue with Google” (turn on Google in Supabase Auth first)')}${chk('sm6',S.toggles?.faq!==false,'Show the FAQ page')}
    <button class="btn" style="margin-top:12px" onclick="Object.assign(S,{siteMsg:sm1.value.trim(),doorPolicy:sm2.value.trim(),tipOptions:sm3.value.split(',').map(x=>+x).filter(x=>x>=0),noAlcohol:sm4.checked,googleLogin:sm5.checked});S.toggles={...(S.toggles||{}),faq:sm6.checked};saveSet('Site options');renderAnnc()">Save</button></div><form onsubmit="return saveSettings(event)">`);
  if(s==='checkout'){const C=S.checkoutChecks||[];return shell(`<h2>Checkout Instructions</h2><div class="panel"><p class="muted small">Checkboxes customers see before placing an order. Required ones must be checked.</p><div id="ckl">${C.map(c=>`<div class="row ckr" style="flex-wrap:nowrap;margin-bottom:6px"><input value="${esc(c.text)}"><label class="check" style="margin:0;white-space:nowrap"><input type="checkbox" ${c.req?'checked':''}> Required</label></div>`).join('')}</div>
    <button class="btn sm ghost" onclick="ckl.insertAdjacentHTML('beforeend','<div class=&quot;row ckr&quot; style=&quot;flex-wrap:nowrap;margin-bottom:6px&quot;><input placeholder=&quot;e.g. I confirm this order is tax exempt&quot;><label class=&quot;check&quot; style=&quot;margin:0;white-space:nowrap&quot;><input type=&quot;checkbox&quot;> Required</label></div>')">Add checkbox</button>
    <label for="ckt">Message shown above checkout (optional)</label><textarea id="ckt" rows="3">${esc(S.checkoutText||'')}</textarea>
    <button class="btn" style="margin-top:12px" onclick="S.checkoutChecks=[...document.querySelectorAll('.ckr')].map(r=>({text:r.querySelector('input').value.trim(),req:r.querySelectorAll('input')[1].checked})).filter(c=>c.text);S.checkoutText=ckt.value.trim();saveSet('Checkout instructions');route()">Save</button><p class="mini muted">Clear a box’s text to remove it.</p></div>`)}
  if(s==='mode'){const m=S.shopperMode;return f(q).replace('<button class="btn" style="margin-top:14px" onclick="Object.assign(S.shopperMode',`<label for="smsc">Scale mode</label><select id="smsc" style="max-width:240px">${['None','Manual','Auto'].map(v=>`<option ${(m.scale||'Manual')===v?'selected':''}>${v}</option>`).join('')}</select>${chk('smscan',m.scanOnly,'Scan-only: shoppers must scan each item’s barcode')}<button class="btn" style="margin-top:14px" onclick="S.shopperMode.scale=smsc.value;S.shopperMode.scanOnly=smscan.checked;Object.assign(S.shopperMode`)}
  if(s==='slots'){const days=[...Array(14)].map((_,i)=>ymd(new Date(Date.now()+i*864e5))).filter(d=>allWindows(d).length);
    return f(q).replace(/<\/form>|(<button class="btn" style="margin-top:14px" onclick="S.capacity[\s\S]*?<\/button><\/div>)/,m=>m+`<div class="panel tbl-wrap"><h3>Current and next week</h3><table><thead><tr><th>Day</th>${allWindows(days[0]||todayStr()).map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${days.map(d=>`<tr><td>${prettyDate(d)}</td>${allWindows(d).map(s=>{const n=slotLoad(d,s),c=slotCap(d,s);return `<td style="${n>=c?'color:var(--tomato);font-weight:800':''}">${n}/${c}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`)}
  return f(q)})(BO_VIEWS.settings);
function arSave2(){S.areas=[...document.querySelectorAll('.arr2')].map(r=>{const c=r.querySelectorAll('input');return {name:c[0].value.trim(),fee:+c[1].value||0,min:+c[2].value||0,discOver:+c[3].value||0,discFee:c[4].value===''?null:+c[4].value,zips:c[5].value.trim(),active:c[6].checked}}).filter(a=>a.name);
  S.noServiceDays=$('nsd').value.trim();S.pickupFee=$('puf').value===''?null:+$('puf').value;syncTowns();saveSet('Service areas');route()}

/* ---------- Customers: groups, bulk group, filters ---------- */
BO_VIEWS.customers=q=>{const t=(q.get('q')||'').toLowerCase(),g=q.get('g')||'',fl=q.get('fl')||'';const byE={};ORDERS.filter(o=>o.status!=='Canceled').forEach(o=>(byE[o.email]=byE[o.email]||[]).push(o));
  let list=USERS.filter(u=>(u.role||'customer')==='customer'&&(!t||((u.first||'')+' '+(u.last||'')+' '+u.email+' '+(u.phone||'')).toLowerCase().includes(t))&&(!g||u.group===g));
  if(fl==='never')list=list.filter(u=>!byE[u.email]);if(fl==='cart')list=list.filter(u=>(u.cart||[]).length);if(fl==='vip')list=list.filter(u=>u.vip);if(fl==='blocked')list=list.filter(u=>u.blocked);
  const groups=[...new Set(USERS.map(u=>u.group).filter(Boolean))].sort();
  window._cx=list.map(u=>({First:u.first||'',Last:u.last||'',Email:u.email,Phone:u.phone||'',Town:u.town||(u.addresses||[])[0]?.town||'',Group:u.group||'',Orders:(byE[u.email]||[]).length,Spent:+(byE[u.email]||[]).reduce((a,o)=>a+(o.final||o.total),0).toFixed(2),CartItems:(u.cart||[]).length}));
  return head('Customers',`${list.length.toLocaleString()} customers`,`<button class="btn sm ghost" onclick="xlsx(window._cx,'Customers','CenterFresh_Customers.xlsx')">Export to Excel</button>`)+
  `<div class="fbar"><div><label>Search</label><input type="search" value="${esc(q.get('q')||'')}" placeholder="Name, email, phone" onkeydown="if(event.key==='Enter')hashSet('q',this.value)"></div><div><label>Group</label><select onchange="hashSet('g',this.value)"><option value="">All groups</option>${groups.map(x=>`<option ${x===g?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div><label>Show</label><select onchange="hashSet('fl',this.value)">${[['','Everyone'],['never','Never ordered'],['cart','Has items in cart'],['vip','VIP'],['blocked','Blocked']].map(([v,l])=>`<option value="${v}" ${fl===v?'selected':''}>${l}</option>`).join('')}</select></div></div>
  <div class="bulkbar"><b id="cxn">0 selected</b><input id="cxg" placeholder="Group name" style="max-width:200px" list="cxgl"><datalist id="cxgl">${groups.map(x=>`<option value="${esc(x)}">`).join('')}</datalist><button class="btn sm" onclick="bulkGroup()">Bulk group</button><button class="btn sm ghost" onclick="cxg.value='';bulkGroup()">Remove from group</button></div>
  <div class="panel tbl-wrap"><table><thead><tr><th><input type="checkbox" onchange="document.querySelectorAll('.cxc').forEach(c=>c.checked=this.checked);cxCnt()" aria-label="Select all"></th><th>Name</th><th>Contact</th><th>Group</th><th>Orders</th><th>Spent</th><th>Last order</th><th>Cart</th></tr></thead><tbody>${list.slice(0,500).map(u=>{const os=byE[u.email]||[];return `<tr class="rowlink" onclick="if(!event.target.closest('input,a'))go('/admin/customer/${encodeURIComponent(u.email)}')"><td><input type="checkbox" class="cxc" value="${esc(u.email)}" onchange="cxCnt()" aria-label="Select"></td><td><b>${esc(((u.first||'')+' '+(u.last||'')).trim()||'—')}</b>${u.vip?' <span class="tagx">VIP</span>':''}${u.blocked?' <span class="tagx red">Blocked</span>':''}</td><td class="mini">${esc(u.email)}<br>${esc(u.phone||'')}</td><td class="mini">${esc(u.group||'')}</td><td>${os.length}</td><td>${money(os.reduce((a,o)=>a+(o.final||o.total),0))}</td><td class="mini">${os.length?new Date(Math.max(...os.map(o=>o.created))).toLocaleDateString():'—'}</td><td>${(u.cart||[]).length||''}</td></tr>`}).join('')||'<tr><td colspan="8" class="muted">No customers yet. They appear here when they create an account on the site.</td></tr>'}</tbody></table>${list.length>500?'<p class="mini muted">Showing the first 500 — search or export for the rest.</p>':''}</div>`};
function cxCnt(){$('cxn').textContent=document.querySelectorAll('.cxc:checked').length+' selected'}
function bulkGroup(){const em=[...document.querySelectorAll('.cxc:checked')].map(c=>c.value),g=$('cxg').value.trim();if(!em.length){toast('Select customers first');return}USERS.forEach(u=>{if(em.includes(u.email))u.group=g||undefined});act(`${g?'Grouped':'Ungrouped'} ${em.length} customers${g?' → '+g:''}`);saveAll();route()}
window.cuReset=async function(e){if(!confirm(`Send a password reset email to ${e}?`))return;const {error}=await sbc.auth.resetPasswordForEmail(e,{redirectTo:location.origin+location.pathname});if(error){toast('Couldn’t send: '+error.message);return}act('Sent password reset to '+e);toast('Reset email sent')};

/* ---------- Banners with dates and a phone picture ---------- */
window.bnEdit=function(i){const b=i!=null?BANNERS[i]:{img:'',h:'',p:'',l:'#/specials',c:'Shop now'};modal(`<h2>${i!=null?'Edit':'Add'} banner</h2>${b.img?`<img src="${esc(b.img)}" alt="" style="width:100%;border-radius:8px">`:''}<div class="grid2"><div><label for="bn0">Desktop picture (about 1800 × 560)</label><input id="bn0" type="file" accept="image/*"></div><div><label for="bnm">Phone picture (optional, about 900 × 560)</label><input id="bnm" type="file" accept="image/*"></div></div>
  <label for="bn1">Headline</label><input id="bn1" value="${esc(b.h||'')}"><label for="bn2">Text</label><input id="bn2" value="${esc(b.p||'')}"><div class="grid2"><div><label for="bn3">Button text</label><input id="bn3" value="${esc(b.c||'')}"></div><div><label for="bn4">Button link</label><input id="bn4" value="${esc(b.l||'')}" placeholder="#/specials"></div><div><label for="bn5">Show from</label><input id="bn5" type="date" value="${b.from||''}"></div><div><label for="bn6">Expires</label><input id="bn6" type="date" value="${b.to||''}"></div></div>
  <button class="btn" style="margin-top:14px" onclick="bnStore2(${i??-1})">Save</button>`)};
window.bnStore2=async function(i){const f=$('bn0').files[0],fm=$('bnm').files[0];let img=i>=0?BANNERS[i].img:'',mimg=i>=0?BANNERS[i].mimg||'':'';if(f)img=await shrink(f,1800);if(fm)mimg=await shrink(fm,900);if(!img){toast('Choose a picture');return}
  const b={img,mimg,h:$('bn1').value,p:$('bn2').value,c:$('bn3').value,l:$('bn4').value||'#/',from:$('bn5').value,to:$('bn6').value};if(i>=0)BANNERS[i]=b;else BANNERS.push(b);closeModal();bnSave()};
BO_VIEWS.banners=(f=>()=>f()+`<p class="mini muted">Banners with dates show only between their start and expiry dates. ${activeBanners().length} showing today.</p>`)(BO_VIEWS.banners);

/* ---------- Deli menus with dates, desktop & phone pictures ---------- */
S.deliMenus=S.deliMenus||{};
window.vDeli=function(){const M=S.deliMenus,t=todayStr(),imgs=DB.get('menuImages',{}),sid=s=>'m-'+s.replace(/\W/g,'');
  const secs=Object.keys(DELI_MENU).filter(s=>{const m=M[s]||{};return m.hidden!==true&&(!m.from||m.from<=t)&&(!m.to||m.to>=t)});
  return `<div class="wrap"><h1 style="margin-top:26px">Deli & Catering Menu</h1><p class="muted">For simchas, Shabbos and every occasion. Call the store to order catering${S.phone?' — <a href="tel:'+esc(S.phone)+'">'+esc(S.phone)+'</a>':''}.</p>
   <div class="deli-cards">${secs.map(s=>`<a href="#/deli" onclick="event.preventDefault();document.getElementById('${sid(s)}').scrollIntoView({behavior:'smooth'})"><img src="${esc(M[s]?.banner||mimg(DELI_IMG[s][1]))}" alt="" loading="lazy"><b>${esc(s)}</b></a>`).join('')}</div>
   ${secs.map(s=>{const m=M[s]||{},pic=(innerWidth<620&&m.mimg)||m.img||imgs[s];return `<section class="blk" id="${sid(s)}"><img class="deli-hdr" src="${esc(m.banner||mimg(DELI_IMG[s][0]))}" alt="${esc(s)}" loading="lazy">${m.note?`<p>${esc(m.note)}</p>`:''}
     ${pic?`<div class="menu-card"><img src="${esc(pic)}" alt="${esc(s)} menu" style="width:100%"></div>`:`<p class="muted">Call the store for the ${esc(s)} menu and prices.</p>`}</section>`}).join('')}</div>`};
BO_VIEWS.menus=()=>head('Deli Menu','Each menu section: printed menu pictures for desktop and phone, dates, and a note.')+`<div class="menu-sec">${Object.keys(DELI_MENU).map(s=>{const m=S.deliMenus[s]||{},img=m.img||DB.get('menuImages',{})[s];return `<div class="menu-card"><h3>${esc(s)}</h3>${img?`<img src="${esc(img)}" alt="" style="max-height:160px;object-fit:cover;width:100%">`:'<p class="small muted">No menu picture yet</p>'}
  <label>Desktop menu picture</label><input type="file" accept="image/*" onchange="dmPic(${qa(s)},'img',this.files[0])"><label>Phone menu picture</label><input type="file" accept="image/*" onchange="dmPic(${qa(s)},'mimg',this.files[0])">
  <div class="grid2"><div><label>Show from</label><input type="date" value="${m.from||''}" onchange="dmSet(${qa(s)},'from',this.value)"></div><div><label>Until</label><input type="date" value="${m.to||''}" onchange="dmSet(${qa(s)},'to',this.value)"></div></div>
  <label>Note</label><input value="${esc(m.note||'')}" onchange="dmSet(${qa(s)},'note',this.value)"><label class="check"><input type="checkbox" ${m.hidden?'checked':''} onchange="dmSet(${qa(s)},'hidden',this.checked)"> Hide this section</label></div>`}).join('')}</div>`;
function dmSet(s,k,v){S.deliMenus[s]=S.deliMenus[s]||{};S.deliMenus[s][k]=v;saveSet('Deli menu '+s)}
async function dmPic(s,k,f){if(!f)return;dmSet(s,k,await shrink(f,1600));route()}

/* ---------- Discounts: start date and order-number rules ---------- */
window.dcEdit=function(i){const d=i!=null?S.discounts[i]:{code:'',type:'%',amount:10,min:0,starts:'',expires:'',maxUses:0,once:false,nth:'',active:true};modal(`<h2>${i!=null?'Edit':'New'} coupon code</h2><label for="dc1">Code</label><input id="dc1" value="${esc(d.code)}" style="text-transform:uppercase">
  <div class="grid2"><div><label for="dc2">Type</label><select id="dc2"><option value="%" ${d.type==='%'?'selected':''}>Percent off</option><option value="$" ${d.type==='$'?'selected':''}>Dollars off</option></select></div><div><label for="dc3">Amount</label><input id="dc3" type="number" step="0.01" value="${d.amount}"></div>
  <div><label for="dc9">Starts</label><input id="dc9" type="date" value="${d.starts||''}"></div><div><label for="dc5">Ends</label><input id="dc5" type="date" value="${d.expires||''}"></div>
  <div><label for="dc4">Minimum order ($)</label><input id="dc4" type="number" value="${d.min||0}"></div><div><label for="dc6">Total uses allowed (0 = unlimited)</label><input id="dc6" type="number" value="${d.maxUses||0}"></div>
  <div><label for="dc10">Only for the customer’s order number</label><input id="dc10" type="number" min="1" value="${d.nth||''}" placeholder="e.g. 1 = first order, 4 = fourth"></div></div>
  ${chk('dc7',d.once,'Once per customer')}${chk('dc8',d.active,'Active')}<button class="btn" style="margin-top:14px" onclick="dcSave2(${i??-1})">Save</button>`)};
window.dcSave2=function(i){const d={code:$('dc1').value.trim().toUpperCase(),type:$('dc2').value,amount:+$('dc3').value||0,min:+$('dc4').value||0,starts:$('dc9').value,expires:$('dc5').value,maxUses:+$('dc6').value||0,nth:$('dc10').value?+$('dc10').value:'',once:$('dc7').checked,active:$('dc8').checked};
  if(!d.code||!d.amount){toast('Code and amount required');return}if(S.discounts.some((x,j)=>x.code===d.code&&j!==i)){toast('That code already exists');return}if(i>=0)S.discounts[i]={...S.discounts[i],...d};else S.discounts.push(d);closeModal();saveSet('Coupon '+d.code);route()};
BO_VIEWS.discounts=(f=>()=>f().replace('<th>Expires</th>','<th>Ends</th>')+`<p class="mini muted">Examples: <b>WELCOME10</b> — 10% off, order number 1. <b>FOURTH20</b> — 20% off, order number 4.</p>`)(BO_VIEWS.discounts);

/* ---------- Edit Circular: flyer pages ---------- */
S.flyer=S.flyer||{title:'Our Flyer',from:'',to:'',pages:[]};
BO_VIEWS.circular=(f=>()=>{const F=S.flyer;return head('Edit Circular','Upload the printed flyer pages and pick the deals.')+`<div class="panel"><h3>Flyer pages</h3><div class="grid2"><div><label for="fy1">Flyer title</label><input id="fy1" value="${esc(F.title||'')}" onchange="S.flyer.title=this.value;saveSet('Flyer')"></div><div class="grid2" style="gap:0 8px"><div><label for="fy2">From</label><input id="fy2" type="date" value="${F.from||''}" onchange="S.flyer.from=this.value;saveSet('Flyer')"></div><div><label for="fy3">To</label><input id="fy3" type="date" value="${F.to||''}" onchange="S.flyer.to=this.value;saveSet('Flyer')"></div></div></div>
   <div class="row" style="margin:12px 0;gap:10px">${(F.pages||[]).map((u,i)=>`<div style="text-align:center"><img src="${esc(u)}" alt="" style="height:140px;border:1px solid var(--line);border-radius:8px"><div class="row" style="justify-content:center;gap:4px"><button class="btn sm ghost" onclick="fyMove(${i},-1)" aria-label="Move left">‹</button><span class="mini">${i+1}</span><button class="btn sm ghost" onclick="fyMove(${i},1)" aria-label="Move right">›</button><button class="linkbtn red" onclick="S.flyer.pages.splice(${i},1);saveSet('Flyer');route()">Remove</button></div></div>`).join('')||'<p class="muted">No pages yet.</p>'}</div>
   <label for="fyp">Add pages (select one or more pictures, in order)</label><input id="fyp" type="file" accept="image/*" multiple onchange="fyAdd(this.files)"><p class="mini muted">Customers see the pages under “Our Flyer” with page numbers, a grid view and printing.</p></div>`+f().replace(/^[\s\S]*?<\/div><\/div>/,'')})(BO_VIEWS.circular);
async function fyAdd(files){S.flyer.pages=S.flyer.pages||[];for(const f of files)S.flyer.pages.push(await shrink(f,1600));saveSet('Flyer pages');route()}
function fyMove(i,d){const a=S.flyer.pages,j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];saveSet('Flyer');route()}

/* ---------- Recipes (shoppable) ---------- */
let RCP=DB.get('recipes',[]);const saveRcp=()=>DB.set('recipes',RCP);
BO_VIEWS.recipes=()=>head('Recipes','Shoppable recipes customers can add to their cart in one tap.',`<button class="btn sm lime" onclick="rcEdit()">Add recipe</button>`)+
  `<div class="panel tbl-wrap"><table><thead><tr><th></th><th>Recipe</th><th>Category</th><th>Time</th><th></th></tr></thead><tbody>${RECIPES.map(r=>`<tr><td>${r.img||RECIPE_PHOTOS[r.id]?`<img src="${esc(r.img||RECIPE_PHOTOS[r.id])}" alt="" style="width:64px;height:44px;object-fit:cover;border-radius:6px">`:r.emoji||''}</td><td><b>${esc(r.title)}</b><div class="mini muted">${r.ing.length} ingredients${RCP.some(x=>x.id===r.id)?'':' · built-in sample'}</div></td><td>${esc(r.cat)}</td><td>${r.time} min</td><td>${RCP.some(x=>x.id===r.id)?`<button class="btn sm ghost" onclick="rcEdit('${r.id}')">Edit</button> <button class="btn sm ghost" onclick="if(confirm('Delete recipe?')){RCP=RCP.filter(x=>x.id!=='${r.id}');RECIPES.splice(RECIPES.findIndex(x=>x.id==='${r.id}'),1);saveRcp();route()}">Delete</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;
function rcEdit(id){const r=id?RCP.find(x=>x.id===id):{title:'',cat:RECIPE_CATS[0],chef:S.brand?.name||'',diet:'Parve',holiday:'',time:30,serves:4,ing:[],steps:[]};
  modal(`<h2>${id?'Edit':'Add'} recipe</h2><label for="rc1">Title</label><input id="rc1" value="${esc(r.title)}"><div class="grid2"><div><label for="rc2">Category</label><select id="rc2">${RECIPE_CATS.map(c=>`<option ${c===r.cat?'selected':''}>${c}</option>`).join('')}</select></div><div><label for="rc3">Meat / dairy / parve</label><select id="rc3">${['Meat','Dairy','Parve'].map(c=>`<option ${c===r.diet?'selected':''}>${c}</option>`).join('')}</select></div><div><label for="rc4">Minutes</label><input id="rc4" type="number" value="${r.time}"></div><div><label for="rc5">Serves</label><input id="rc5" type="number" value="${r.serves}"></div><div><label for="rc8">Chef</label><input id="rc8" value="${esc(r.chef||'')}"></div><div><label for="rc9">Holiday</label><input id="rc9" value="${esc(r.holiday||'')}"></div></div>
   <label for="rc6">Ingredients — one per line. Add “| product word” to link a product, e.g. “2 lb chicken cutlets | chicken cutlets”</label><textarea id="rc6" rows="6">${esc(r.ing.map(([t,n])=>n&&n!==t?t+' | '+n:t).join('\n'))}</textarea>
   <label for="rc7">Steps — one per line</label><textarea id="rc7" rows="5">${esc(r.steps.join('\n'))}</textarea><label for="rcf">Photo</label><input id="rcf" type="file" accept="image/*"><button class="btn lime" style="margin-top:14px" onclick="rcSave(${qa(id||'')})">Save recipe</button>`);$('mbox').classList.add('wide')}
async function rcSave(id){const f=$('rcf').files[0],old=id?RCP.find(x=>x.id===id):null;const r={id:id||'u'+Date.now(),title:$('rc1').value.trim(),cat:$('rc2').value,diet:$('rc3').value,time:+$('rc4').value||0,serves:+$('rc5').value||1,chef:$('rc8').value.trim(),holiday:$('rc9').value.trim(),emoji:'🍽️',pop:60,
  ing:$('rc6').value.split('\n').map(l=>l.trim()).filter(Boolean).map(l=>{const [t,n]=l.split('|').map(x=>x.trim());return [t,n||t.replace(/^[\d½¼¾\/.\s]+(lb|lbs|oz|cups?|tbsp|tsp|cloves?|cans?|bunch|heads?)?\s*/i,'')]}),steps:$('rc7').value.split('\n').map(l=>l.trim()).filter(Boolean),img:old?.img||''};
  if(!r.title){toast('Title required');return}if(f)r.img=await shrink(f,1200);
  if(old)Object.assign(old,r);else RCP.push(r);const k=RECIPES.findIndex(x=>x.id===r.id);if(k>=0)RECIPES[k]=r;else RECIPES.push(r);saveRcp();act('Saved recipe '+r.title);closeModal();route()}

/* ---------- Products Import: automatic import while the back office is open ---------- */
BO_VIEWS.import=(f=>()=>{const a=S.api||{},last=SYS.find(x=>/^API import/.test(x.m));
  return f()+`<div class="panel"><h3>Automatic product & price import</h3><p class="small muted">Runs the API import from <a href="#/admin/api">API Import</a> on a schedule. Because the site has no server of its own, it runs while a back office page is open on any staff computer.</p>
   <div class="kv"><b>Status</b><span>${S.autoImport?.on?'On — every '+S.autoImport.mins+' minutes':'Off'}</span><b>Last import</b><span>${last?fmtT(last.t)+' — '+esc(last.m):'Never'}</span><b>Source</b><span>${esc(a.url||'Not set up')}</span></div>
   <div class="row" style="margin-top:12px"><label class="row" style="margin:0">Every <input id="aim" type="number" min="15" value="${S.autoImport?.mins||120}" style="width:80px"> minutes</label><button class="btn sm lime" onclick="S.autoImport={on:true,mins:Math.max(15,+aim.value||120)};saveSet('Automatic import');route()">Start</button><button class="btn sm ghost" onclick="S.autoImport={on:false,mins:+aim.value||120};saveSet('Automatic import');route()">Cancel</button><button class="btn sm ghost" onclick="go('/admin/api')">Run now</button></div></div>`})(BO_VIEWS.import);
setInterval(()=>{const ai=S.autoImport;if(!ai?.on||!S.api?.url||!isStaffU()||!can('import'))return;const last=SYS.find(x=>/^API import/.test(x.m));if(last&&Date.now()-last.t<ai.mins*6e4)return;
  if(typeof apiImport==='function'&&$('apres')==null){const div=document.createElement('div');div.id='apres';div.hidden=true;document.body.appendChild(div);
    try{const orig=window.apiCollect;window.apiCollect=()=>{};apiImport().finally(()=>{window.apiCollect=orig;div.remove()})}catch(e){div.remove()}}},60000);

/* ---------- User Roles on real accounts ---------- */
BO_VIEWS.roles=()=>{if(roleOf()!=='admin')return head('User Roles')+'<p class="muted">Only admins and store managers can manage staff.</p>';
  const st=USERS.filter(u=>u.role&&u.role!=='customer').sort((a,b)=>a.role.localeCompare(b.role));
  return head('User Roles',`${st.length} staff accounts`,`<button class="btn sm lime" onclick="urFind()">Add staff member</button>`)+
  `<div class="panel" style="background:var(--leaf);border-color:transparent"><b>How to add staff:</b> ask the person to create an account on the website with their work email, then click <b>Add staff member</b>, find their email and choose a role.</div>
  <div class="panel tbl-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>PIN</th><th>Status</th><th></th></tr></thead><tbody>${st.map(u=>`<tr><td><b>${esc(uname(u.email))}</b></td><td class="mini">${esc(u.email)}</td><td>${esc(ROLES[u.role]||u.role)}</td><td>${u.pin?'Set':'—'}</td><td>${u.active===false?'<span class="tagx red">Inactive</span>':'<span class="tagx">Active</span>'}</td><td><button class="btn sm ghost" onclick="urEdit(${qa(u.email)})">Edit</button></td></tr>`).join('')}</tbody></table></div>
  <div class="panel tbl-wrap"><h3>What each role can open</h3><table><thead><tr><th>Section</th>${Object.keys(ROLES).filter(r=>r!=='customer').map(r=>`<th style="writing-mode:vertical-rl;transform:rotate(180deg);white-space:nowrap">${ROLES[r]}</th>`).join('')}</tr></thead><tbody>${BO_MENU.flatMap(g=>g[1]).map(([k,l])=>`<tr><td>${l}</td>${Object.keys(ROLES).filter(r=>r!=='customer').map(r=>`<td>${['admin','store_manager','chain_manager'].includes(r)||(ACCESS[r]||[]).includes(k)?'✓':''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`};
function urFind(){modal(`<h2>Add staff member</h2><label for="urq">Their account email</label><input id="urq" type="email" placeholder="name@example.com" oninput="urRes()"><div id="urr" style="margin-top:10px"></div>`);setTimeout(()=>$('urq').focus(),50)}
function urRes(){const t=$('urq').value.trim().toLowerCase();if(t.length<3){$('urr').innerHTML='';return}const r=USERS.filter(u=>u.email.includes(t)).slice(0,8);
  $('urr').innerHTML=r.length?r.map(u=>`<div class="row" style="justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--line)"><span><b>${esc(uname(u.email))}</b><div class="mini muted">${esc(u.email)} · ${esc(ROLES[u.role]||u.role)}</div></span><button class="btn sm" onclick="urEdit(${qa(u.email)})">Choose</button></div>`).join(''):`<p class="muted small">No account with that email yet. Ask them to create one on the website first (Sign in → Create account), then search again.</p>`}
window.urEdit=function(e){const u=USERS.find(x=>x.email===e);if(!u)return;const can2=realRole()==='admin';
  modal(`<h2>${esc(uname(e))}</h2><p class="muted">${esc(e)}</p><div class="grid2"><div><label for="ur1">First name</label><input id="ur1" value="${esc(u.first||'')}"></div><div><label for="ur2">Last name</label><input id="ur2" value="${esc(u.last||'')}"></div></div>
   <label for="ur4">Role</label><select id="ur4">${Object.entries(ROLES).filter(([k])=>k!=='admin'||can2).map(([k,l])=>`<option value="${k}" ${k===u.role?'selected':''}>${l}</option>`).join('')}</select>
   <label for="ur6">4-digit PIN for Standalone Mode <span class="muted small">(blank = keep)</span></label><input id="ur6" type="password" inputmode="numeric" maxlength="4" style="max-width:140px">${chk('ur7',u.active!==false,'Active (can sign in)')}
   <p class="mini muted">To change their password, they use “Forgot password” on the sign-in window.</p><div class="row"><button class="btn lime" style="margin-top:14px" onclick="urSave2(${qa(e)})">Save</button></div>`)};
window.urSave2=function(e){const u=USERS.find(x=>x.email===e),role=$('ur4').value,pin=$('ur6').value;if(pin&&!/^\d{4}$/.test(pin)){toast('PIN must be 4 digits');return}
  if(e===me&&role!=='admin'&&realRole()==='admin'&&!USERS.some(x=>x.role==='admin'&&x.email!==me&&x.active!==false)){toast('Keep at least one active admin');return}
  Object.assign(u,{first:$('ur1').value.trim(),last:$('ur2').value.trim(),role,active:$('ur7').checked});if(pin)u.pin=hash(pin);act(`Staff ${e}: ${ROLES[role]}${u.active?'':' (inactive)'}`);saveAll();closeModal();route();toast('Saved — they’ll see their tools the next time they open the site')};

/* ---------- wrench: Edit Home Page ---------- */
const _openWrenchCF=window.openWrench;window.openWrench=function(){_openWrenchCF();$('mbox').insertAdjacentHTML('beforeend',`<h3 style="margin-top:18px">Edit Home Page</h3><div class="row"><a class="btn sm ghost" href="#/admin/banners" onclick="closeModal()">Banners</a><a class="btn sm ghost" href="#/admin/featured" onclick="closeModal()">Featured products</a><a class="btn sm ghost" href="#/admin/circular" onclick="closeModal()">Flyer</a><a class="btn sm ghost" href="#/admin/branding" onclick="closeModal()">Colors & logo</a></div>`)};

/* ---------- staff: report a data issue from the product page ---------- */
const _vProductBO=window.vProduct;window.vProduct=id=>{let h=_vProductBO(id);if(isStaffU()&&can('check')&&prod(id))h=h.replace('<span class="loc">',`<span class="row" style="float:right;gap:6px"><button class="btn sm ghost" onclick="editP('${id}')">✎ Edit</button><button class="btn sm ghost" onclick="reportIssue('${id}')">Report issue</button></span><span class="loc">`);return h};

/* first-time owner welcome */
if(isStaffU()&&realRole()==='admin'&&!S.welcomed){setTimeout(()=>{modal(`<h2>Welcome to your Center Fresh store</h2><p>You’re signed in as the store admin. A few things to set up first:</p><ol><li><b>Settings → Store General</b>: address, phone, hours.</li><li><b>Settings → Service Areas</b>: your delivery towns, fees and minimums.</li><li><b>Products Import</b>: download the price sheet and upload your prices.</li><li><b>Store Branding</b>: your logo and colors.</li><li><b>User Roles</b>: give staff accounts their roles.</li></ol><button class="btn lime" onclick="S.welcomed=1;saveSet('Welcome');closeModal();go('/admin/settings?s=general')">Start with Store General</button>`)},800)}

/* ---------- never trust money fields a customer could edit: rebuild discount & totals from store rules ---------- */
function recheckOrder(o){if(['Charged','Canceled'].includes(o.status))return false;const d=o.code?(S.discounts||[]).find(x=>x.code===o.code):null;
  const rule=d?{code:d.code,type:d.type,amount:d.amount}:null,before=CF.canon([o.discRule||null,+(o.total||0).toFixed(2)]);o.discRule=rule;if(!rule)o.code='';recalc(o);
  if(o.final!=null&&o.status==='Processed')finalize(o);return CF.canon([o.discRule||null,+(o.total||0).toFixed(2)])!==before}
if(isStaffU()){let n=0;ORDERS.forEach(o=>{if(recheckOrder(o)){n++;o.log.push({t:Date.now(),m:'Totals rechecked against store prices and coupons'})}});if(n)saveAll()}
const _finalizeCF=window.finalize;window.finalize=function(o){const d=o.code?(S.discounts||[]).find(x=>x.code===o.code):null;o.discRule=d?{code:d.code,type:d.type,amount:d.amount}:null;return _finalizeCF(o)};
